.version 8.3
.target sm_89
.address_size 64

.visible .entry conv2d_kernel(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 bias_ptr,
    .param .u64 y_ptr,
    .param .s32 N,
    .param .s32 Cin,
    .param .s32 Cout,
    .param .s32 H,
    .param .s32 W,
    .param .s32 KH,
    .param .s32 KW,
    .param .s32 strideH,
    .param .s32 strideW,
    .param .s32 padH,
    .param .s32 padW,
    .param .s32 dilH,
    .param .s32 dilW,
    .param .s32 Hout,
    .param .s32 Wout,
    .param .s32 total
)
{
    .reg .s32 %r<64>;
    .reg .s64 %rd<32>;
    .reg .f32 %f<8>;
    .reg .pred %p<12>;

    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [bias_ptr];
    ld.param.u64 %rd4, [y_ptr];

    ld.param.s32 %r1, [N];
    ld.param.s32 %r2, [Cin];
    ld.param.s32 %r3, [Cout];
    ld.param.s32 %r4, [H];
    ld.param.s32 %r5, [W];
    ld.param.s32 %r6, [KH];
    ld.param.s32 %r7, [KW];
    ld.param.s32 %r8, [strideH];
    ld.param.s32 %r9, [strideW];
    ld.param.s32 %r10, [padH];
    ld.param.s32 %r11, [padW];
    ld.param.s32 %r12, [dilH];
    ld.param.s32 %r13, [dilW];
    ld.param.s32 %r14, [Hout];
    ld.param.s32 %r15, [Wout];
    ld.param.s32 %r16, [total];

    mov.u32 %r20, %ctaid.x;
    mov.u32 %r21, %ntid.x;
    mov.u32 %r22, %tid.x;
    mad.lo.s32 %r23, %r20, %r21, %r22;

    setp.ge.s32 %p1, %r23, %r16;
    @%p1 bra DONE;

    // decode ow, oh, oc, n
    rem.s32 %r30, %r23, %r15;
    div.s32 %r31, %r23, %r15;
    rem.s32 %r32, %r31, %r14;
    div.s32 %r33, %r31, %r14;
    rem.s32 %r34, %r33, %r3;
    div.s32 %r35, %r33, %r3;

    mov.f32 %f1, 0f00000000;

    mov.s32 %r41, 0;
LOOP_IC:
    setp.ge.s32 %p2, %r41, %r2;
    @%p2 bra END_IC;

    mov.s32 %r42, 0;
LOOP_KH:
    setp.ge.s32 %p3, %r42, %r6;
    @%p3 bra END_KH;

    mul.lo.s32 %r50, %r32, %r8;
    sub.s32 %r50, %r50, %r10;
    mul.lo.s32 %r51, %r42, %r12;
    add.s32 %r50, %r50, %r51;

    setp.lt.s32 %p4, %r50, 0;
    setp.ge.s32 %p5, %r50, %r4;
    or.pred %p6, %p4, %p5;
    @%p6 bra SKIP_KH;

    mov.s32 %r43, 0;
LOOP_KW:
    setp.ge.s32 %p7, %r43, %r7;
    @%p7 bra END_KW;

    mul.lo.s32 %r52, %r30, %r9;
    sub.s32 %r52, %r52, %r11;
    mul.lo.s32 %r53, %r43, %r13;
    add.s32 %r52, %r52, %r53;

    setp.lt.s32 %p8, %r52, 0;
    setp.ge.s32 %p9, %r52, %r5;
    or.pred %p10, %p8, %p9;
    @%p10 bra SKIP_KW;

    mad.lo.s32 %r54, %r35, %r2, %r41;
    mad.lo.s32 %r54, %r54, %r4, %r50;
    mad.lo.s32 %r54, %r54, %r5, %r52;

    mad.lo.s32 %r55, %r34, %r2, %r41;
    mad.lo.s32 %r55, %r55, %r6, %r42;
    mad.lo.s32 %r55, %r55, %r7, %r43;

    mul.wide.s32 %rd10, %r54, 4;
    add.s64 %rd11, %rd1, %rd10;
    ld.global.f32 %f2, [%rd11];

    mul.wide.s32 %rd12, %r55, 4;
    add.s64 %rd13, %rd2, %rd12;
    ld.global.f32 %f3, [%rd13];

    fma.rn.f32 %f1, %f2, %f3, %f1;

SKIP_KW:
    add.s32 %r43, %r43, 1;
    bra LOOP_KW;
END_KW:

SKIP_KH:
    add.s32 %r42, %r42, 1;
    bra LOOP_KH;
END_KH:

    add.s32 %r41, %r41, 1;
    bra LOOP_IC;
END_IC:

    mul.wide.s32 %rd20, %r34, 4;
    add.s64 %rd21, %rd3, %rd20;
    ld.global.f32 %f4, [%rd21];
    add.f32 %f1, %f1, %f4;

    mad.lo.s32 %r56, %r35, %r3, %r34;
    mad.lo.s32 %r56, %r56, %r14, %r32;
    mad.lo.s32 %r56, %r56, %r15, %r30;

    mul.wide.s32 %rd14, %r56, 4;
    add.s64 %rd15, %rd4, %rd14;
    st.global.f32 [%rd15], %f1;

