    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        N, Cin, H, W = x.shape
        KH, KW = self.kernel_size
        strideH = strideW = self.stride
        padH, padW = self.padding
        dilH, dilW = self.dilation

        Hout = (H + 2 * padH - dilH * (KH - 1) - 1) // strideH + 1
        Wout = (W + 2 * padW - dilW * (KW - 1) - 1) // strideW + 1

        weight = self.conv2d.weight.contiguous()
        if self.conv2d.bias is not None:
            bias = self.conv2d.bias.contiguous()
        else:
            bias = torch.zeros(self.out_channels, device=x.device, dtype=x.dtype)

        y = torch.empty((N, self.out_channels, Hout, Wout), device=x.device, dtype=x.dtype)

        total = N * self.out_channels * Hout * Wout
        block = (256, 1, 1)
        grid_x = (total + block[0] - 1) // block[0]
        grid = (grid_x, 1, 1)

        module = _get_ptx_module()
        module.launch(
            "conv2d_kernel",
            grid=grid,
            block=block,
            arguments=[
                x, weight, bias, y,
                i32(N), i32(Cin), i32(self.out_channels),
                i32(H), i32(W), i32(KH), i32(KW),
                i32(strideH), i32(strideW),
                i32(padH), i32(padW),
                i32(dilH), i32(dilW),
                i32(Hout), i32(Wout), i32(total),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y
